 static StreamWriter log; static int seq=0;
 static double U(double v){return v/1000.0;}
 static void Say(string s){Console.WriteLine(s);log.WriteLine(s);log.Flush();}
 static string PlaneName(int axis){int idx=0;Feature f=(Feature)m.FirstFeature();while(f!=null){if(f.GetTypeName2()=="RefPlane"){if(idx==axis)return f.Name;idx++;}f=(Feature)f.GetNextFeature();}throw new Exception("No plane");}
 // axis 0 = world Z, 1 = world Y, 2 = world X. Sketch points are transformed from world coordinates.
 static Sketch Start(int axis,double pos){m.ClearSelection2(true);string p=PlaneName(axis);if(!m.Extension.SelectByID2(p,"PLANE",0,0,0,false,0,null,0))throw new Exception("Select plane "+p);
 if(Math.Abs(pos)>0.00001){int constraint=8; if(pos<0)constraint|=256;var rf=(RefPlane)m.FeatureManager.InsertRefPlane(constraint,U(Math.Abs(pos)),0,0,0,0);if(rf==null)throw new Exception("Offset plane");m.ClearSelection2(true);((Feature)rf).Select2(false,0);}
 m.SketchManager.InsertSketch(true);m.SketchManager.AddToDB=true;m.SketchManager.DisplayWhenAdded=false;var s=(Sketch)m.GetActiveSketch2();if(s==null)throw new Exception("Sketch failed");return s;}
 static double[] Pt(Sketch s,double x,double y,double z){return (double[])((MathPoint)((MathPoint)math.CreatePoint(new double[]{U(x),U(y),U(z)})).MultiplyTransform(s.ModelToSketchTransform)).ArrayData;}
 static void Rect(Sketch s,int a,double pos,double u1,double v1,double u2,double v2){double[] p,q;
 if(a==0){p=Pt(s,u1,v1,pos);q=Pt(s,u2,v2,pos);}else if(a==1){p=Pt(s,u1,pos,v1);q=Pt(s,u2,pos,v2);}else{p=Pt(s,pos,u1,v1);q=Pt(s,pos,u2,v2);}m.SketchManager.CreateCornerRectangle(p[0],p[1],0,q[0],q[1],0);}
 static void Circle(Sketch s,int a,double pos,double u,double v,double r){double[] p=a==0?Pt(s,u,v,pos):(a==1?Pt(s,u,pos,v):Pt(s,pos,u,v));m.SketchManager.CreateCircleByRadius(p[0],p[1],0,U(r));}
 static Feature End(Sketch s,int a,double depth,bool cut,string name){m.SketchManager.AddToDB=false;m.SketchManager.DisplayWhenAdded=true;m.SketchManager.InsertSketch(true);m.ClearSelection2(true);((Feature)s).Select2(false,0);bool flip=false;Feature f;
 if(cut)f=m.FeatureManager.FeatureCut3(true,false,!flip,0,0,U(depth),0,false,false,false,false,0,0,false,false,false,false,false,true,true,true,true,false,0,0,false);
 else f=m.FeatureManager.FeatureExtrusion2(true,false,flip,0,0,U(depth),0,false,false,false,false,0,0,false,false,false,false,true,true,true,0,0,false);
 if(f==null)throw new Exception("Feature failed: "+name);f.Name=name+"_"+(++seq);return f;}
 static void Box(double x1,double y1,double z1,double x2,double y2,double z2,string name){var s=Start(0,z1);Rect(s,0,z1,x1,y1,x2,y2);End(s,0,z2-z1,false,name);}
 static void CutRect(int a,double p,double u1,double v1,double u2,double v2,double depth,string name){var s=Start(a,p);Rect(s,a,p,u1,v1,u2,v2);End(s,a,depth,true,name);}
 static void Holes(int a,double p,double[][] xy,double r,double d,string name){var s=Start(a,p);foreach(var pt in xy)Circle(s,a,p,pt[0],pt[1],r);End(s,a,d,true,name);}
