 static void Save(string name,bool stl){m.ForceRebuild3(false);int e=0,w=0;string path=Path.Combine(output,name+".SLDPRT");if(!m.Extension.SaveAs(path,0,1,null,ref e,ref w)||e!=0)throw new Exception("Save "+name+" "+e);Say("Saved "+name+" warnings="+w);if(stl){sw.SetUserPreferenceIntegerValue((int)swUserPreferenceIntegerValue_e.swExportStlUnits,0);sw.SetUserPreferenceToggle((int)swUserPreferenceToggle_e.swSTLDontTranslateToPositive,true);if(!m.Extension.SaveAs(Path.Combine(output,name+".stl"),0,1,null,ref e,ref w))throw new Exception("STL "+name);}
 var bs=(object[])((PartDoc)m).GetBodies2(0,false);Say("Solids "+(bs==null?0:bs.Length));if(bs==null||bs.Length==0)throw new Exception("No solid "+name);foreach(Body2 b in bs)Say("BBox "+String.Join(",",(double[])b.GetBodyBox()));m.ClearSelection2(true);m.SetUserPreferenceToggle((int)swUserPreferenceToggle_e.swDisplayPlanes,false);m.ShowNamedView2("*Isometric",7);((ModelView)m.ActiveView).DisplayMode=4;m.ViewZoomtofit2();m.Extension.SaveAs(Path.Combine(output,name+".png"),0,1,null,ref e,ref w);}
