 static Component2 Add(AssemblyDoc a,string name,MathTransform tr){string path=Path.Combine(output,name+".SLDPRT");int e=0,w=0;sw.OpenDoc6(path,1,1,"",ref e,ref w);int ae=0;sw.ActivateDoc3(m.GetTitle(),false,0,ref ae);var comp=a.AddComponent5(path,0,"",false,"",0,0,0);if(comp==null)throw new Exception("Insert "+name);m.ClearSelection2(true);comp.Select4(false,null,false);a.UnfixComponent();comp.Transform2=tr;m.ClearSelection2(true);comp.Select4(false,null,false);a.FixComponent();Say("Component "+comp.Name2+" transform="+String.Join(",",(double[])comp.Transform2.ArrayData));return comp;}
 static MathTransform Move(double x,double y,double z){return (MathTransform)math.CreateTransform(new double[]{1,0,0,0,1,0,0,0,1,U(x),U(y),U(z),1,0,0,0});}
 static MathTransform Tilt(){double a=-15*Math.PI/180,c=Math.Cos(a),s=Math.Sin(a),py=-60,pz=49.5;double ty=py-c*py+s*pz,tz=pz-s*py-c*pz;return (MathTransform)math.CreateTransform(new double[]{1,0,0,0,c,s,0,-s,c,0,U(ty),U(tz),1,0,0,0});}
