 static void DeletePrefix(string prefix){m.ClearSelection2(true);var f=(Feature)m.FirstFeature();while(f!=null){if(f.Name.StartsWith(prefix)){f.Select2(false,0);if(!m.Extension.DeleteSelection2(1))throw new Exception("Delete "+prefix);return;}f=(Feature)f.GetNextFeature();}throw new Exception("Missing "+prefix);}
 static double FloorZ(double y,double worldz){double a=-15*Math.PI/180;return 49.5+(worldz-49.5-Math.Sin(a)*(y+60))/Math.Cos(a);}
 static void PolygonYZ(double x,double[][] pts,double depth,bool cut,string name){var sk=Start(2,x);for(int k=0;k<pts.Length;k++){var p=Pt(sk,x,pts[k][0],pts[k][1]);var q=Pt(sk,x,pts[(k+1)%pts.Length][0],pts[(k+1)%pts.Length][1]);m.SketchManager.CreateLine(p[0],p[1],0,q[0],q[1],0);}End(sk,2,depth,cut,name);}
